"""Freeze compact local evidence; omit large binaries and inert bytecode explicitly."""
import hashlib,json,shutil
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]
HERE=Path(__file__).resolve().parent
OUT=ROOT/'evidence/fringe-packing-followup-v1'
SOURCES=['outputs/fringe-atlas-mip-review-v1', 'outputs/fringe-packed-candidate-preparation-v1', 'outputs/panda-fringe-packed-v1', 'outputs/fringe-packed-eevee-preview-preparation-v1', 'outputs/panda-fringe-packed-eevee-preview-v1', 'outputs/fringe-packed-visual-review-v1', 'outputs/fringe-packed-independent-audit-v1', 'outputs/fringe-packed-independent-audit-v2', 'outputs/fringe-packing-save-v1']
def sha(path):
 h=hashlib.sha256()
 with path.open('rb') as stream:
  for chunk in iter(lambda:stream.read(1024*1024),b''):h.update(chunk)
 return h.hexdigest()
files=[]
for folder in SOURCES:
 for path in sorted((ROOT/folder).rglob('*')):
  assert not path.is_symlink(),path
  if path.is_file():files.append(path)
assert len(files)<=512
rows=[];omitted=[];objects={};total=0
for path in files:
 size=path.stat().st_size
 assert size<=128*1024*1024,path
 row={'origin':str(path.relative_to(ROOT)),'bytes':size,'sha256':sha(path)}
 if size>2*1024*1024 or path.suffix in ('.glb','.blend','.pyc'):
  row['reason']='Large model/native file remains local; compact evidence is not a remote binary backup.' if path.suffix!='.pyc' else 'Generated bytecode omitted; exact Python source retained.'
  omitted.append(row);continue
 key=row['sha256']
 if key not in objects:
  objects[key]='payload/'+key+'/'+path.name
  total+=size
 row['saved_path']=objects[key];rows.append(row)
assert total<=16*1024*1024,(total,'bundle exceeds bound')
OUT.mkdir()
for row in rows:
 src=ROOT/row['origin'];dest=OUT/row['saved_path']
 assert sha(src)==row['sha256']
 if not dest.exists():
  dest.parent.mkdir(parents=True,exist_ok=True);shutil.copyfile(src,dest)
 assert sha(dest)==row['sha256']
readme='# Fur texture-packing follow-up\n\n**A verified local component improvement, not completed hands-off quality.**\n\nThe manifest maps exact local origins to immutable deduplicated payloads. It\npreserves the modeled filtering screen/permutation, actual derivative recipe,\nindependent exported-file audit, eight matched EEVEE images and parent review.\nLarge GLB/Blend files remain local with exact hashes; this is not a binary backup.\nThe prior renderer/color/shading controls are in `../fringe-shading-color-v1`.\n\nReordering all4,800 unchanged texture cells removes most dark-region bright\nflecks in the matched front and flight poses. Geometry, normals, rig and actions\nstay unchanged. Actual float32 UV samples retain the9,600-tip color gate.\nFiltered alpha changes with packing; this does not isolate color bleed as the\nsole cause. Cheek/shoulder defects and sparse coat remain. No approved asset,\ngallery, default or automatic fur profile was replaced.\n\nOne local derivative and one3.629-second native preview ran; no new Meshy,\nMeta, image-generation or pipeline-role AI call. Exact settings, bounds, source\nhashes and rejected interpretations remain in the preparations and review.\nThis is an existing assisted panda, not fresh prompt/Studio acceptance.\nDeep mip isolation and Muse-equivalent fur remain unproved. Source rights and\nprovenance are inherited, not independently verified. Completed preparations\nare append-only and must not be rerun in their old output folders.\n'
(OUT/'README.md').write_text(readme)
manifest={'schema_version':1,'project_relative_root':'tools/avatar-assets','status':'actual_texture_packing_improved_not_quality_accepted','quality_approved':False,'muse_parity':False,'hands_off_acceptance':False,'origin_mappings':rows,'omitted_origin_files':omitted,'source_directories':SOURCES,'payload_object_count':len(objects),'payload_object_bytes':total,'retained_origin_count':len(rows),'bundle_limits':{'max_bytes':16*1024*1024,'max_source_files':512},'new_provider_or_pipeline_role_calls':0,'artifacts':[{'path':'README.md','bytes':(OUT/'README.md').stat().st_size,'sha256':sha(OUT/'README.md')}],'limitations':['Not a remote backup or complete recreation of omitted binaries.','Sampled appearance and nominal-tip colors do not establish dense fur, isolated GPU causality or fresh Studio acceptance.']}
(OUT/'manifest.json').write_text(json.dumps(manifest,indent=2,sort_keys=True)+'\n')
for row in rows:assert sha(ROOT/row['origin'])==row['sha256'] and sha(OUT/row['saved_path'])==row['sha256']
receipt={'manifest_sha256':sha(OUT/'manifest.json'),'bundle_files':len(list(OUT.rglob('*')))-len([p for p in OUT.rglob('*') if p.is_dir()]),'bundle_bytes':sum(p.stat().st_size for p in OUT.rglob('*') if p.is_file()),'origins':len(rows),'omitted_files':len(omitted),'all_retained_copies_verified':True}
(HERE/'receipt.json').write_text(json.dumps(receipt,indent=2)+'\n')
print(json.dumps(receipt,indent=2))
